-- Institute external links (website, social media, other resources).
-- Idempotent: safe to run on every PostgreSQL instance before deploying the release.
CREATE TABLE IF NOT EXISTS "InstituteLinks"
(
    "Id"           integer GENERATED BY DEFAULT AS IDENTITY,
    "InstituteId"  integer                     NOT NULL,
    "LinkTitle"    character varying(100)      NOT NULL,
    "LinkType"     integer                     NOT NULL DEFAULT 0,
    "Url"          character varying(2048)     NOT NULL,
    "DisplayOrder" integer                     NOT NULL DEFAULT 0,
    "IsActive"     boolean                     NOT NULL DEFAULT true,
    "CreatedBy"    text,
    "CreatedAt"    timestamp without time zone NOT NULL,
    "EditedBy"     text,
    "EditedAt"     timestamp without time zone NOT NULL,
    "MACAddress"   text,
    CONSTRAINT "PK_InstituteLinks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InstituteLinks_Institute_InstituteId" FOREIGN KEY ("InstituteId")
        REFERENCES "Institute" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_InstituteLinks_InstituteId_DisplayOrder"
    ON "InstituteLinks" ("InstituteId", "DisplayOrder");
